					if (Call(CMD_IF_FIRST, new long[] { IF_FIRST_ATTACK }) != 0 && tokusei != (long)Pml.TokuseiNo.SEISINRYOKU &&
						tokusei != (long)Pml.TokuseiNo.HUKUTUNOKOKORO && tokusei != (long)Pml.TokuseiNo.ITAZURAGOKORO)
					{
						PRINTF("投げつけるがひるませる効果で自分が素早いので230ランダムプラス\n");
