			if (Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_1_4BAI }) != 0)
				return;
			if (Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_1_2BAI }) != 0)
				return;
			var myWeight = Call(CMD_GET_WEIGHT, new long[] { CHECK_ATTACK });
			var weight = Call(CMD_GET_WEIGHT, new long[] { CHECK_DEFENCE });
			var tokusei = Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE });
			long ratio = weight != 0 ? myWeight / weight : 0; // unguarded sdiv in the binary: ARM64 yields 0 on /0
			if (tokusei == (long)Pml.TokuseiNo.HEVHIMETARU)
				ratio /= 2;
			if (Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK }) == (long)Pml.TokuseiNo.HEVHIMETARU)
				ratio *= 2;
			if (Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_2BAI }) != 0 ||
				Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_4BAI }) != 0)
			{
				if (ratio >= 3)
				{
					PRINTF("効果抜群で体重が3倍（威力80）以上なので200ランダムプラス\n");
					if (Call(CMD_IF_RND_UNDER, new long[] { 200 }) != 0)
						ScoreCtrl(2);
				}
			}
			else if (ratio >= 5)
			{
				PRINTF("体重が5倍（威力120）以上なので180ランダムプラス\n");
				if (Call(CMD_IF_RND_UNDER, new long[] { 180 }) != 0)
					ScoreCtrl(1);
			}
			else if (ratio == 4)
			{
				PRINTF("体重が4倍（威力100）以上なので128ランダムプラス\n");
				if (Call(CMD_IF_RND_UNDER, new long[] { 128 }) != 0)
					ScoreCtrl(1);
			}
			else if (ratio <= 1)
			{
				PRINTF("体重が2倍（威力40）未満なので220ランダムマイナス\n");
				if (Call(CMD_IF_RND_UNDER, new long[] { 220 }) != 0)
					ScoreCtrl(-1);
			}
		}
