		private void ExpertAI_Seq_318() {
			var type1 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE1 });
			var type2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE2 });
			string message;
			switch ((Pml.MonsNo)Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK }))
			{
				case Pml.MonsNo.DOKUKURAGE:
					if (type1 != POKETYPE_DENKI && type1 != POKETYPE_ESPER && type2 != POKETYPE_DENKI && type2 != POKETYPE_ESPER)
						return;
					message = "自分がドククラゲで相手が電気、エスパーなので180ランダムプラス\n";
					break;
				case Pml.MonsNo.GENGAA:
					if (type1 != POKETYPE_AKU && type1 != POKETYPE_ESPER && type2 != POKETYPE_AKU && type2 != POKETYPE_ESPER)
						return;
					message = "自分がゲンガーで相手が悪、エスパーなので180ランダムプラス\n";
					break;
				case Pml.MonsNo.SUTAAMII:
					if (type1 != POKETYPE_AKU && type1 != POKETYPE_DENKI && type1 != POKETYPE_KUSA &&
						type2 != POKETYPE_AKU && type2 != POKETYPE_DENKI && type2 != POKETYPE_KUSA)
						return;
					message = "自分がスターミーで相手が悪、電気、草なので180ランダムプラス\n";
					break;
				case Pml.MonsNo.OMUSUTAA:
					if (type1 != POKETYPE_KUSA && type1 != POKETYPE_DENKI && type2 != POKETYPE_KUSA && type2 != POKETYPE_DENKI)
						return;
					message = "自分がオムスターで相手が草、電気なので180ランダムプラス\n";
					break;
				case Pml.MonsNo.MYUU:
					if (type1 != POKETYPE_AKU && type2 != POKETYPE_AKU)
						return;
					message = "自分がミュウで相手が悪なので180ランダムプラス\n";
					break;
				case Pml.MonsNo.RATHIASU:
					if (type1 != POKETYPE_AKU && type1 != POKETYPE_KOORI && type1 != POKETYPE_MIZU &&
						type2 != POKETYPE_AKU && type2 != POKETYPE_KOORI && type2 != POKETYPE_MIZU)
						return;
					message = "自分がラティアスで相手が悪、氷、水なので180ランダムプラス\n";
					break;
				default:
					return;
			}
			PRINTF(message);
			if (Call(CMD_IF_RND_UNDER, new long[] { 180 }) != 0)
				ScoreCtrl(1);
		}
